{
  "findings": [
    {
      "check_id": "CKV_AWS_273",
      "title": "Ensure IAM user has attached policies or is part of a group",
      "resource": "aws_iam_user.privesc11-PutGroupPolicy-user",
      "severity": "LOW",
      "explanation": "The IAM user privesc11-PutGroupPolicy-user is not part of any group and has no policies attached, potentially leading to privilege escalation if not managed properly."
    }
  ],
  "patched_code": ```hcl
resource "aws_iam_user" "privesc11-PutGroupPolicy-user" {
  name = "privesc11-PutGroupPolicy-user"
  path = "/"
}

resource "aws_iam_group" "privesc11-PutGroupPolicy-group" {
  name = "privesc11-PutGroupPolicy-group"
  path = "/"
}

resource "aws_iam_group_membership" "privesc11-PutGroupPolicy-membership" {
  name  = "privesc11-PutGroupPolicy-membership"
  users = [aws_iam_user.privesc11-PutGroupPolicy-user.name]
  group = aws_iam_group.privesc11-PutGroupPolicy-group.name
}

resource "aws_iam_policy" "privesc11-PutGroupPolicy-policy" {
  name        = "privesc11-PutGroupPolicy-policy"
  description = "Minimal policy for the user"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "iam:GetUser",
          "iam:GetGroup"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_group_policy_attachment" "privesc11-PutGroupPolicy-attach" {
  group      = aws_iam_group.privesc11-PutGroupPolicy-group.name
  policy_arn = aws_iam_policy.privesc11-PutGroupPolicy-policy.arn
}
```,
  "fix_summary": "Added an IAM group with a minimal policy attached and added the user to this group to ensure the user is part of a managed group with controlled permissions."
}
